        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Der Mensch ist gut und will nicht, daß man vor einem andern als ihm selbst krieche.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Ein Schmeichler ist's selten aus bloßem Eigennutz, sondern aus Charakter; denn er schmeichelt Niedrigen wie Hohen.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Eine lange Zeit lernt man darum die Menschen nicht kennen, weil man sie überall für besser hält als sich.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Es gibt Menschen, denen jedes Lob Tadel ist, das nicht das größte ist.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Es ist leichter, die Menschen zu lieben als zu ertragen - viele heftig zu lieben, als keinen zu hassen.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Feststehende philosophische Worte sind gefährlich – man bringt sein ganzes Anschauungssystem darunter – und dann versteht man fremde Worte nicht, die man sonst verstände.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "In der Liebe wird der Ernst der Jungfrau bezaubern; in der Ehe, die selber ein langer Ernst ist, möchte leichtes Scherzen und Bescherzen der Welt besser einschlagen.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "An ungebildeten Leuten ärgert einen Eigennutz nicht.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Jede Freude füllt, jeder Schmerz leert dich, aber in jener hat noch Sehnsucht Platz, in diesem noch Zuversicht.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Warum lieben wir die Tugend an andern zehnmal mehr als an uns? Warum fühlen wir so viel Wärme gegen einen Aufopfernden und halten's für Schuldigkeit bei uns? Einmal müssen wir uns irren.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Man ist neugierig, die Stellen im Buche zu lesen, die ein anderer unterstrichen hat.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "In den Dämmerungen regiert das Herz.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Lass sich doch keine Seele vom Glauben an Gott in ihrer Lebens-Geschichte etwa dadurch abneigen, daß sie zu klein dafür sei in der Menge der Geister und Sonnen.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Gute Weiber gönnen einander alles, ausgenommen Kleider, Männer und Flachs.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Ich kenne nur eine Sache, die süßer ist, als ein Buch zu machen, nämlich eines zu entwerfen.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "In phantasieichen Menschen liegen, wie in heißen Ländern oder auf Bergen, alle Extreme eng beieinander.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Der Mensch ist nie so schön, als wenn er um Verzeihung bittet oder selber verzeiht.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Manche Dichter geraten unter dem Malen schlechter Charaktere oft so ins Nachahmen derselben hinein, wie Kinder, wenn sie träumen zu pissen, wirklich ihr Wasser lassen.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Mancher wird ein freier Diogenes, nicht wenn er in dem Fasse, sondern wenn dieses in ihm wohnt.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Ungück kann sich wie ein Skorpion in jede Ecke verkriechen.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Die Leidenschaft macht die besten Beobachtung und die elendesten Schlüsse. Sie ist ein Fernrohr, dessen Feld desto heller, je enger es ist.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Wenn man beim Stiche der Biene oder des Schicksals nicht stillehält, so reißet der Stachel ab und bleibt zurück.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Ein Charakter ist ein Fels, an welchem gestrandete Schiffer landen und anstürmende scheitern.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Das körperliche Herz sei das Muster des geistigen: verletzbar, empfindlich, rege und warm, aber ein derber, frei fortschlagender Muskel hinter dem Knochengitter, und seine zarten Nerven sind schwer zu finden.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Die weibliche Kleider-Liebe hat samt der Reinlichkeit, welche gleichsam auf der Grenzscheide zwischen Leib und Sittlichkeit wohnt, eine Wand- und Tür-Nachbarin, nämlich Herzens-Reinheit.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Die Wiederholung ist die Mutter - nicht bloß des Studierens, sondern auch der Bildung.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Ein verdrießlicher Gott ist ein Widerspruch oder der Teufel.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Einen traurigen Mann erduld' ich, aber kein trauriges Kind.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Einzelne Regeln ohne den Geist der Erziehung sind ein Wörterbuch ohne Sprachlehre.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Hinter einem voranziehenden Gott würden alle Menschen Götter. Tilgt ihr aber das Ideal aus der Brust, so verschwindet damit Tempel, Opferaltar und alles.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Jede gute Erzählung, so wie gute Dichtung, umgibt sich von selber mit Lehren.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Jedes Ich ist Persönlichkeit, folglich geistige Individualität.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Mit einer Kindheit voll Liebe aber kann man ein halbes Leben hindurch für die kalte Welt haushalten.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Armut ist die einzige Last, die schwerer wird, je mehr Geliebte daran tragen.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Dass du gewiss in Bayreuth selig sein wirst, so sehr sind dessen Häuser und Berge zu loben.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Der Hauptfehler des Menschen bleibt, dass er so viele kleine hat.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Hier auf dem offenen Meere der Welt, mitten unter hundert Schiffen, kann ich Dir nicht durch das Sprachrohr der Presse das zuschreien, was ich Dir viel lieber nahe an Deinem Angesicht und an Deiner Brust zuflüstern möchte.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Nie vergesse der Dichter über der Zukunft, die ihm eigentlich heller vorschimmert, die Forderungen der Gegenwart und also des nur an diese angeschmiedeten Lesers.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Die bloße Empfindung schafft nicht den Dichter, aber der bloße Dichter auch nicht jene. Im ersten Irrtum ist der Jüngling, im zweiten der Kritiker.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Der Humor, als das umgekehrt Erhabene, vernichtet nicht das Einzelne, sondern das Endliche durch den Kontrast mit der Idee.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Alle plötzlichen Dämmerungen sind nur die der Sonnenfinsternisse und also keine wachsende, sondern ebenso plötzlich verschwindende.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Berlin ist mehr ein Welttheil, als eine Stadt, wo sich aus der größeren Menge leichter eine gesellige Einsamkeit erwählen ließe. Da fänden Sie Ihren ruhigsten Hafen in Deutschland.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Das Alter ist nicht trübe, weil darin unsre Freuden, sondern weil unsre Hoffnungen aufhören.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Der Dichter gleicht der Saite: Er selber macht sich unsichtbar, wenn er sich schwingt und Wohllaut gibt.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Die Erinnerung ist das einzige Paradies, aus welchem wir nicht getrieben werden können.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Die Kunst ist zwar nicht das Brot, aber der Wein des Lebens.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Es hat mich oft verdrüßlich gemacht, daß ich jeder Vorrede, die ich schreibe, ein Buch anhängen muß", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Je älter man wird, desto lieber will man sprechen, und desto weniger schreiben, besonders Briefe.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Mädchen und Gold sind desto weicher, je reiner sie sind.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Nur sein Auge sah alle die tausend Qualen der Menschen bei ihren Untergängen - Diesen Weltschmerz kann er, so zu sagen, nur aushalten durch den Anblick der Seligkeit, die nachher vergütet.", Author = "Jean Paul" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Jean_Paul", Text = "Ser viele sind schon entzükt über ein Buch, wenn nichts darin steht als ihre vorigen Meinung gedrukt.", Author = "Jean Paul" },
        };
